-- Mensaje 182 · SOLO si hay que regresar: deja el Cerebro, la regla, la guía y los guiones 2.7, 2.7c y 2.10 como antes del 182.
-- Si algo no está como lo dejó el 182, falla y NO cambia nada. Después corre doctrina_182_verificar.sql.
DO $do$
DECLARE v int; n int; b text; ps jsonb; t text;
BEGIN
  -- 1. El Cerebro: se borra la versión del 182 y vuelve a activarse la anterior.
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF NOT EXISTS (SELECT 1 FROM public.doctrina WHERE version = v AND section_key = 'pasos' AND is_active AND strpos(body, $t$Un bloqueo no es contestarte: si te dice$t$) > 0) THEN RAISE EXCEPTION 'la versión activa del Cerebro no es la del 182'; END IF;
  SELECT count(*) INTO n FROM public.doctrina WHERE version = v - 1;
  IF n <> 7 THEN RAISE EXCEPTION 'la versión anterior del Cerebro no tiene 7 secciones'; END IF;
  DELETE FROM public.doctrina WHERE version = v;
  UPDATE public.doctrina SET is_active = true WHERE version = v - 1;
  -- 2. La regla opening.pitch_prematuro: un bloqueo no es contestarte; cómo le va es sobre él.
  SELECT resumen INTO t FROM public.reglas WHERE id = 'opening.pitch_prematuro';
  IF t IS NULL OR (length(t) - length(replace(t, $t$Tampoco una pregunta sobre él o sobre cómo le va (la semana, el negocio, la venta, el movimiento), aunque mencione su negocio o sus productos: preguntarle cómo le va no es pedirle información de su operación.$t$, ''))) / length($t$Tampoco una pregunta sobre él o sobre cómo le va (la semana, el negocio, la venta, el movimiento), aunque mencione su negocio o sus productos: preguntarle cómo le va no es pedirle información de su operación.$t$) <> 1 THEN RAISE EXCEPTION 'opening.pitch_prematuro no tiene el texto esperado'; END IF;
  t := replace(t, $t$Tampoco una pregunta sobre él o sobre cómo le va (la semana, el negocio, la venta, el movimiento), aunque mencione su negocio o sus productos: preguntarle cómo le va no es pedirle información de su operación.$t$, $t$Tampoco una pregunta sobre él o sobre cómo le va.$t$);
  IF t IS NULL OR (length(t) - length(replace(t, $t$Ya que te presentaste y el cliente te contestó, preguntar por su operación es descubrimiento y no es esto. Un bloqueo («ahorita ando ocupado», «no me interesa») no es contestarte: después de aceptarlo, la pregunta va sobre él o sobre cómo le va, y preguntarle por su operación ahí todavía es antes de tiempo.$t$, ''))) / length($t$Ya que te presentaste y el cliente te contestó, preguntar por su operación es descubrimiento y no es esto. Un bloqueo («ahorita ando ocupado», «no me interesa») no es contestarte: después de aceptarlo, la pregunta va sobre él o sobre cómo le va, y preguntarle por su operación ahí todavía es antes de tiempo.$t$) <> 1 THEN RAISE EXCEPTION 'opening.pitch_prematuro no tiene el texto esperado'; END IF;
  t := replace(t, $t$Ya que te presentaste y el cliente te contestó, preguntar por su operación es descubrimiento y no es esto. Un bloqueo («ahorita ando ocupado», «no me interesa») no es contestarte: después de aceptarlo, la pregunta va sobre él o sobre cómo le va, y preguntarle por su operación ahí todavía es antes de tiempo.$t$, $t$Ya que te presentaste y el cliente te contestó, preguntar por su operación es descubrimiento y no es esto.$t$);
  UPDATE public.reglas SET resumen = t, updated_at = now() WHERE id = 'opening.pitch_prematuro';
  -- 3. La guía del vendedor: el molde del paso 2 y los bloqueos dicen lo mismo.
  SELECT texto INTO t FROM public.guia_del_vendedor WHERE clave = 'paso_2' AND activa;
  IF t IS NULL OR (length(t) - length(replace(t, $t$Ya que te contestó, empiezan las preguntas de su negocio: eso ya es descubrimiento. Un bloqueo no es contestarte: después de aceptarlo, la pregunta sigue siendo sobre él o sobre cómo le va.$t$, ''))) / length($t$Ya que te contestó, empiezan las preguntas de su negocio: eso ya es descubrimiento. Un bloqueo no es contestarte: después de aceptarlo, la pregunta sigue siendo sobre él o sobre cómo le va.$t$) <> 1 THEN RAISE EXCEPTION 'la guía (paso_2) no tiene el texto esperado'; END IF;
  UPDATE public.guia_del_vendedor SET texto = replace(texto, $t$Ya que te contestó, empiezan las preguntas de su negocio: eso ya es descubrimiento. Un bloqueo no es contestarte: después de aceptarlo, la pregunta sigue siendo sobre él o sobre cómo le va.$t$, $t$Ya que te contestó, empiezan las preguntas de su negocio: eso ya es descubrimiento.$t$) WHERE clave = 'paso_2';
  SELECT texto INTO t FROM public.guia_del_vendedor WHERE clave = 'cuando_bloqueos' AND activa;
  IF t IS NULL OR (length(t) - length(replace(t, $t$Lo aceptas («claro»), no lo discutes y sigues con tu plática en el mismo turno, sin pedir permiso: con una pregunta sobre él o sobre cómo le va, no de su negocio ni ofreciéndole nada.$t$, ''))) / length($t$Lo aceptas («claro»), no lo discutes y sigues con tu plática en el mismo turno, sin pedir permiso: con una pregunta sobre él o sobre cómo le va, no de su negocio ni ofreciéndole nada.$t$) <> 1 THEN RAISE EXCEPTION 'la guía (cuando_bloqueos) no tiene el texto esperado'; END IF;
  UPDATE public.guia_del_vendedor SET texto = replace(texto, $t$Lo aceptas («claro»), no lo discutes y sigues con tu plática en el mismo turno, sin pedir permiso: con una pregunta sobre él o sobre cómo le va, no de su negocio ni ofreciéndole nada.$t$, $t$Lo aceptas («claro»), no lo discutes y sigues con tu plática en el mismo turno, sin pedir permiso.$t$) WHERE clave = 'cuando_bloqueos';
  -- 4. Los guiones: 2.7 y 2.7c califican pitch_prematuro; el 2.10 dice lo mismo que la regla.
  SELECT practice_script INTO ps FROM public.nodes WHERE id = '2.7';
  IF ps IS NULL OR ps->>'version' <> '2.1.1' THEN RAISE EXCEPTION 'el guion 2.7 no está en la versión 2.1.1 del 182 (está en %)', ps->>'version'; END IF;
  IF jsonb_array_length(ps->'failure_criteria') <> 5 OR ps #> '{failure_criteria,4}' IS DISTINCT FROM $t${"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promoción o motivo de venta, o le pregunta por su operación comercial (su proveedor, sus precios, sus marcas, qué se le mueve, cómo escoge a quién comprarle) antes de tiempo. Aceptar el bloqueo no da permiso de ofrecer ni de preguntarle por su negocio: un bloqueo no es contestarte. Después del AIR sigue con su plática, con una pregunta sobre él o sobre cómo le va; no con producto, no pidiendo el pedido y no con preguntas de su operación. Tampoco le pregunta por su operación antes de haberle dicho quién es y por qué pasó. Preguntarle cómo le va (la semana, el negocio, la venta, el movimiento) es sobre él aunque mencione sus productos, y no es esta falla."}$t$::jsonb THEN RAISE EXCEPTION 'el guion 2.7 no termina en la falla que agregó el 182'; END IF;
  t := ps->>'notes';
  IF t IS NULL OR right(t, length($t$ · 2.1.1 (mensaje 182, 25-nov-2026): pitch_prematuro también aquí, como en el resto del mundo 2. Un bloqueo no es contestarte: después del AIR, la pregunta va sobre él o sobre cómo le va (Emilio).$t$)) <> $t$ · 2.1.1 (mensaje 182, 25-nov-2026): pitch_prematuro también aquí, como en el resto del mundo 2. Un bloqueo no es contestarte: después del AIR, la pregunta va sobre él o sobre cómo le va (Emilio).$t$ THEN RAISE EXCEPTION 'las notas del guion 2.7 no terminan en la nota del 182'; END IF;
  ps := ps #- '{failure_criteria,4}';
  ps := jsonb_set(ps, '{notes}', to_jsonb(left(t, length(t) - length($t$ · 2.1.1 (mensaje 182, 25-nov-2026): pitch_prematuro también aquí, como en el resto del mundo 2. Un bloqueo no es contestarte: después del AIR, la pregunta va sobre él o sobre cómo le va (Emilio).$t$))));
  ps := jsonb_set(ps, '{version}', to_jsonb('2.0.4'::text));
  UPDATE public.nodes SET practice_script = ps WHERE id = '2.7';
  SELECT practice_script INTO ps FROM public.nodes WHERE id = '2.7c';
  IF ps IS NULL OR ps->>'version' <> '1.1.1' THEN RAISE EXCEPTION 'el guion 2.7c no está en la versión 1.1.1 del 182 (está en %)', ps->>'version'; END IF;
  IF jsonb_array_length(ps->'failure_criteria') <> 6 OR ps #> '{failure_criteria,5}' IS DISTINCT FROM $t${"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promoción o motivo de venta, o le pregunta por su operación comercial (su proveedor, sus precios, sus marcas, qué se le mueve, cómo escoge a quién comprarle) antes de tiempo. Aceptar el bloqueo no da permiso de ofrecer ni de preguntarle por su negocio: un bloqueo no es contestarte. Después del AIR sigue con su plática, con una pregunta sobre él o sobre cómo le va; no con producto, no pidiendo el pedido y no con preguntas de su operación. Tampoco le pregunta por su operación antes de haberle dicho quién es y por qué pasó. Preguntarle cómo le va (la semana, el negocio, la venta, el movimiento) es sobre él aunque mencione sus productos, y no es esta falla. Después del segundo bloqueo, quedar de regresar con dos opciones de día («¿el jueves o el viernes?») no es ofrecer: no es esta falla."}$t$::jsonb THEN RAISE EXCEPTION 'el guion 2.7c no termina en la falla que agregó el 182'; END IF;
  t := ps->>'notes';
  IF t IS NULL OR right(t, length($t$ · 1.1.1 (mensaje 182, 25-nov-2026): pitch_prematuro también aquí, como en el resto del mundo 2. Un bloqueo no es contestarte: después del AIR, la pregunta va sobre él o sobre cómo le va (Emilio).$t$)) <> $t$ · 1.1.1 (mensaje 182, 25-nov-2026): pitch_prematuro también aquí, como en el resto del mundo 2. Un bloqueo no es contestarte: después del AIR, la pregunta va sobre él o sobre cómo le va (Emilio).$t$ THEN RAISE EXCEPTION 'las notas del guion 2.7c no terminan en la nota del 182'; END IF;
  ps := ps #- '{failure_criteria,5}';
  ps := jsonb_set(ps, '{notes}', to_jsonb(left(t, length(t) - length($t$ · 1.1.1 (mensaje 182, 25-nov-2026): pitch_prematuro también aquí, como en el resto del mundo 2. Un bloqueo no es contestarte: después del AIR, la pregunta va sobre él o sobre cómo le va (Emilio).$t$))));
  ps := jsonb_set(ps, '{version}', to_jsonb('1.0.5'::text));
  UPDATE public.nodes SET practice_script = ps WHERE id = '2.7c';
  SELECT practice_script INTO ps FROM public.nodes WHERE id = '2.10';
  IF ps IS NULL OR ps->>'version' <> '2.1.7' THEN RAISE EXCEPTION 'el guion 2.10 no está en la versión 2.1.7 (está en %)', ps->>'version'; END IF;
  t := ps #>> '{failure_criteria,6,description}';
  IF ps #>> '{failure_criteria,6,id}' IS DISTINCT FROM 'pitch_prematuro' OR t IS NULL OR (length(t) - length(replace(t, $t$Ya que se presentó y el cliente le contestó, preguntar por su negocio es descubrimiento y no es esta falla. Un bloqueo no es contestarte: después de aceptarlo, la pregunta va sobre él o sobre cómo le va.$t$, ''))) / length($t$Ya que se presentó y el cliente le contestó, preguntar por su negocio es descubrimiento y no es esta falla. Un bloqueo no es contestarte: después de aceptarlo, la pregunta va sobre él o sobre cómo le va.$t$) <> 1 THEN RAISE EXCEPTION 'el guion 2.10 no tiene la descripción esperada de pitch_prematuro'; END IF;
  ps := jsonb_set(ps, '{failure_criteria,6,description}', to_jsonb(replace(t, $t$Ya que se presentó y el cliente le contestó, preguntar por su negocio es descubrimiento y no es esta falla. Un bloqueo no es contestarte: después de aceptarlo, la pregunta va sobre él o sobre cómo le va.$t$, $t$Ya que se presentó y el cliente le contestó, preguntar por su negocio es descubrimiento y no es esta falla.$t$)));
  t := ps->>'notes';
  IF t IS NULL OR right(t, length($t$ · 2.1.7 (mensaje 182, 25-nov-2026): un bloqueo no es contestarte, como la regla (Emilio).$t$)) <> $t$ · 2.1.7 (mensaje 182, 25-nov-2026): un bloqueo no es contestarte, como la regla (Emilio).$t$ THEN RAISE EXCEPTION 'las notas del guion 2.10 no terminan en la nota del 182'; END IF;
  ps := jsonb_set(ps, '{notes}', to_jsonb(left(t, length(t) - length($t$ · 2.1.7 (mensaje 182, 25-nov-2026): un bloqueo no es contestarte, como la regla (Emilio).$t$))));
  ps := jsonb_set(ps, '{version}', to_jsonb('2.1.6'::text));
  UPDATE public.nodes SET practice_script = ps WHERE id = '2.10';
  -- 5. Verificación.
  SELECT count(*) INTO n FROM public.doctrina WHERE is_active;
  IF n <> 7 THEN RAISE EXCEPTION 'el Cerebro activo tiene % secciones, no 7', n; END IF;
END
$do$;
